def populate_specialist_reply_count(apps, schema_editor):
    """将历史咨询数扣除历史机器人完结回复，保留已有数据的可读性。"""
    for model_name in ("StoreMetric", "StoreMetricSnapshot"):
        model = apps.get_model("core", model_name)
        for row in model.objects.all().iterator():
            consultation_count = row.consultation_count or 0
            robot_completed_reply_count = row.robot_completed_reply_count or 0
            try:
                row.specialist_reply_count = max(int(consultation_count) - int(robot_completed_reply_count), 0)
            except (TypeError, ValueError):
                row.specialist_reply_count = 0
            row.save(update_fields=["specialist_reply_count"])


